/**
 * terse-complexity-classifier.js
 *
 * Classifies a prompt as "simple" (0) or "complex" (1) using a locally
 * trained DistilBERT ONNX model.  Falls back to null if the model or
 * onnxruntime-node is unavailable — the proxy then uses keyword rules.
 *
 * Model artifacts expected at: ~/.terse/ml/
 *   complexity-model.onnx   — quantized INT8 ONNX model (~17 MB)
 *   complexity-vocab.json   — WordPiece vocabulary for tokenization
 *
 * Install onnxruntime-node once:
 *   mkdir -p ~/.terse && cd ~/.terse && npm install onnxruntime-node
 *
 * Generated by: ml/train.py
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const os   = require('os');

// ── Paths ────────────────────────────────────────────────────────────────────
const ML_DIR    = path.join(os.homedir(), '.terse', 'ml');
const MODEL_PATH = path.join(ML_DIR, 'complexity-model.onnx');
const VOCAB_PATH = path.join(ML_DIR, 'complexity-vocab.json');

// onnxruntime-node installed in ~/.terse/node_modules/
const ORT_PATHS = [
  path.join(os.homedir(), '.terse', 'node_modules', 'onnxruntime-node'),
  'onnxruntime-node',  // in case it's globally installed
];

// ── State ────────────────────────────────────────────────────────────────────
let session     = null;   // ort.InferenceSession
let tokenizer   = null;   // WordPieceTokenizer instance
let loadDone    = false;
let loadFailed  = false;

// ── WordPiece tokenizer (pure JS, no deps) ────────────────────────────────────
/**
 * Minimal DistilBERT-compatible WordPiece tokenizer.
 *
 * For a complexity classifier we don't need perfect tokenization —
 * correctness at the word level is sufficient.  This implementation:
 *   1. Lowercases + strips accents
 *   2. Splits on whitespace and punctuation
 *   3. Applies greedy longest-match WordPiece using the model's vocabulary
 *   4. Adds [CLS] / [SEP] / padding up to MAX_LEN
 */
class WordPieceTokenizer {
  constructor(vocabData) {
    this.vocab   = vocabData.vocab;   // { token: id }
    this.special = vocabData.special; // { cls, sep, unk, pad }
    this.MAX_LEN = 128;
  }

  encode(text) {
    // Normalise
    text = text.toLowerCase().trim();
    // Strip accents (NFD → remove combining marks)
    text = text.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    // Split: insert spaces around most punctuation
    text = text.replace(/([^\w\s])/g, ' $1 ').replace(/\s+/g, ' ').trim();

    const words = text.split(' ').filter(Boolean);

    const ids       = [this.special.cls];
    const attnMask  = [1];

    for (const word of words) {
      const pieces = this._wordPiece(word);
      for (const id of pieces) {
        ids.push(id);
        attnMask.push(1);
        if (ids.length >= this.MAX_LEN - 1) break;
      }
      if (ids.length >= this.MAX_LEN - 1) break;
    }

    ids.push(this.special.sep);
    attnMask.push(1);

    // Pad to MAX_LEN
    while (ids.length < this.MAX_LEN) {
      ids.push(this.special.pad);
      attnMask.push(0);
    }

    return {
      inputIds:      ids.slice(0, this.MAX_LEN),
      attentionMask: attnMask.slice(0, this.MAX_LEN),
    };
  }

  _wordPiece(word) {
    // Whole-word lookup
    if (word in this.vocab) return [this.vocab[word]];

    const result  = [];
    let remaining = word;
    let isFirst   = true;

    while (remaining.length > 0) {
      let matched = false;
      for (let len = remaining.length; len > 0; len--) {
        const sub = (isFirst ? '' : '##') + remaining.slice(0, len);
        if (sub in this.vocab) {
          result.push(this.vocab[sub]);
          remaining = remaining.slice(len);
          isFirst   = false;
          matched   = true;
          break;
        }
      }
      if (!matched) {
        result.push(this.special.unk);
        break;
      }
    }

    return result.length > 0 ? result : [this.special.unk];
  }
}

// ── Model loading ─────────────────────────────────────────────────────────────
async function loadModel() {
  if (loadDone) return;
  loadDone = true;

  // Check model artifacts exist
  if (!fs.existsSync(MODEL_PATH) || !fs.existsSync(VOCAB_PATH)) {
    // Silently skip — proxy will use keyword rules
    return;
  }

  // Load vocabulary
  try {
    const vocabData = JSON.parse(fs.readFileSync(VOCAB_PATH, 'utf8'));
    tokenizer = new WordPieceTokenizer(vocabData);
  } catch (e) {
    log(`Vocab load failed: ${e.message}`);
    loadFailed = true;
    return;
  }

  // Dynamically require onnxruntime-node from known locations
  let ort = null;
  for (const p of ORT_PATHS) {
    try {
      ort = require(p);
      break;
    } catch (_) {}
  }

  if (!ort) {
    log('onnxruntime-node not found — ML routing disabled');
    log('To enable: cd ~/.terse && npm install onnxruntime-node');
    tokenizer = null;
    loadFailed = true;
    return;
  }

  // Create inference session
  try {
    session = await ort.InferenceSession.create(MODEL_PATH, {
      executionProviders: ['cpu'],
      graphOptimizationLevel: 'all',
      intraOpNumThreads: 2,
    });
    log(`ML complexity model loaded (${(fs.statSync(MODEL_PATH).size / 1e6).toFixed(1)} MB)`);
  } catch (e) {
    log(`ONNX session init failed: ${e.message}`);
    session  = null;
    tokenizer = null;
    loadFailed = true;
  }
}

// ── Inference ─────────────────────────────────────────────────────────────────
/**
 * Classify a prompt.
 *
 * Returns: { label: 'simple'|'complex', confidence: 0–1 }
 *   or null if the model isn't loaded (proxy falls back to keyword rules).
 *
 * Timeout: 80 ms — if inference is slow (cold start on spinning disk etc.)
 * we return null rather than blocking the proxy.
 */
async function classify(text) {
  if (!loadDone) await loadModel();
  if (!session || !tokenizer) return null;

  const start = Date.now();

  try {
    const { inputIds, attentionMask } = tokenizer.encode(text);

    // Build typed arrays for ONNX
    const seq  = inputIds.length;           // should be MAX_LEN (128)
    const idBuf   = new BigInt64Array(seq);
    const maskBuf = new BigInt64Array(seq);
    for (let i = 0; i < seq; i++) {
      idBuf[i]   = BigInt(inputIds[i]);
      maskBuf[i] = BigInt(attentionMask[i]);
    }

    // Load ort lazily (was already required in loadModel)
    const ort = require(ORT_PATHS.find(p => {
      try { require.resolve(p); return true; } catch { return false; }
    }) || ORT_PATHS[1]);

    const feeds = {
      input_ids:      new ort.Tensor('int64', idBuf,   [1, seq]),
      attention_mask: new ort.Tensor('int64', maskBuf, [1, seq]),
    };

    const results = await session.run(feeds);
    const logits  = results['logits'].data;   // Float32Array of length 2

    // Softmax
    const expS = Math.exp(logits[0]);
    const expC = Math.exp(logits[1]);
    const sum  = expS + expC;
    const pSimple  = expS / sum;
    const pComplex = expC / sum;

    const label      = pComplex > pSimple ? 'complex' : 'simple';
    const confidence = Math.max(pSimple, pComplex);

    log(`ML classify (${Date.now() - start}ms): "${text.slice(0, 60)}…" → ${label} (${(confidence * 100).toFixed(1)}%)`);

    return { label, confidence };
  } catch (e) {
    log(`ML inference error: ${e.message}`);
    return null;
  }
}

// ── Timeout wrapper ───────────────────────────────────────────────────────────
async function classifyWithTimeout(text, timeoutMs = 80) {
  return Promise.race([
    classify(text),
    new Promise(resolve => setTimeout(() => resolve(null), timeoutMs)),
  ]);
}

// ── Logging ───────────────────────────────────────────────────────────────────
function log(msg) {
  process.stderr.write(`[terse-ml] ${msg}\n`);
}

// Start loading in background immediately (non-blocking)
loadModel().catch(() => {});

module.exports = {
  classify: classifyWithTimeout,
  loadModel,
  get isAvailable() { return session !== null && tokenizer !== null; },
};
